window.__rgjRes=null; window.__rgjErr=null;
(async () => { try {
  const want = ["Contra", "Mega Man 2"];
  const norm = s => s.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const key  = s => s.toLowerCase().replace(/[^a-z0-9]+/g,'');
  const html = await (await fetch('https://retroachievements.org/gameList.php?system=7')).text();
  const doc = new DOMParser().parseFromString(html,'text/html');
  const byName = {}, byKey = {};
  doc.querySelectorAll('a[href*="/game/"]').forEach(a => {
    const m = a.getAttribute('href').match(/\/game\/(\d+)/); if (!m) return;
    const t = (a.textContent||'').trim(); if (!t) return;
    if (!(norm(t) in byName)) byName[norm(t)] = m[1];
    if (!(key(t) in byKey)) byKey[key(t)] = m[1];
  });
  const findAch = (n,d) => { if (!n || typeof n !== 'object' || d > 8) return null;
    if (Array.isArray(n) && n.length && n[0] && typeof n[0]==='object' && 'title' in n[0] && 'points' in n[0]) return n;
    for (const k in n) { const r = findAch(n[k], d+1); if (r) return r; } return null; };
  const out = { listCount: doc.querySelectorAll('a[href*="/game/"]').length, games: {} };
  for (const t of want) {
    const id = byName[norm(t)] || byKey[key(t)];
    if (!id) { out.games[t] = { missing: true }; continue; }
    const h = await (await fetch('https://retroachievements.org/game/' + id)).text();
    const d2 = new DOMParser().parseFromString(h,'text/html');
    const blob = d2.querySelector('script[type="application/json"]');
    if (!blob) { out.games[t] = { raId: id, nojson: true }; continue; }
    let j; try { j = JSON.parse(blob.textContent); } catch(e) { out.games[t] = { raId: id, badjson: true }; continue; }
    const arr = findAch(j, 0) || [];
    out.games[t] = { raId: Number(id), n: arr.length, ach: arr.map(a => ({ id:a.id, title:a.title, desc:a.description, points:a.points, ratio:a.pointsWeighted, type:a.type||'', awarded:a.unlocksTotal||0 })) };
  }
  window.__rgjRes = JSON.stringify(out);
} catch(e) { window.__rgjErr = String(e && e.stack || e); } })();
